describe('Modal Dialog Animation', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should open modal with animation when button is clicked', () => {
    // Verify modal is closed initially
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Click the button to open modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal appears with animation
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal content is visible
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');
    cy.get('[data-testid="modal-body"]').should('be.visible');

    // Verify close button exists and is clickable
    cy.get('[data-testid="close-modal-button"]').should('be.visible').click();

    // Verify modal closes with animation
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('should handle modal close via backdrop click with animation', () => {
    // Open modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Click backdrop to close modal
    cy.get('[data-testid="modal-backdrop"]').click();

    // Verify modal closes with animation
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify modal is not stuck open
    cy.get('[data-testid="open-modal-button"]').should('be.visible');
  });
});
